package edu.riara.edp.week06;
import javafx.application.Application;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class LayoutsDemo extends Application {public void start(Stage s){TabPane tabs=new TabPane();HBox h=new HBox(10,new Button("One"),new Button("Two"));VBox v=new VBox(10,new Label("Name"),new TextField());BorderPane b=new BorderPane();b.setTop(new Label("Header"));b.setCenter(new Button("Center"));b.setBottom(new Label("Footer"));GridPane g=new GridPane();for(int i=0;i<9;i++)g.add(new Button("Cell "+i),i%3,i/3);for(Node node:new Node[]{h,v,b,g}){Tab tab=new Tab(node.getClass().getSimpleName(),node);tab.setClosable(false);tabs.getTabs().add(tab);}s.setScene(new Scene(tabs,450,300));s.show();}public static void main(String[]a){launch(a);}}